-- aud.inbox_messages: Messages already processed by a consumer, so consumers are idempotent (spec 03 section 7.5)
create table if not exists aud.inbox_messages (
    message_id uuid not null,
    consumer text not null,
    processed_at timestamptz not null,
    constraint pk_inbox_messages primary key (message_id, consumer)
);

-- aud.outbox_messages: Events written in the business transaction; the dispatcher publishes them (spec 03 section 7.5)
create table if not exists aud.outbox_messages (
    id uuid not null,
    occurred_at timestamptz not null,
    event_type text not null,
    aggregate_type text not null,
    aggregate_id uuid not null,
    payload jsonb not null,
    headers jsonb not null default '{}'::jsonb,
    published_at timestamptz,
    constraint pk_outbox_messages primary key (id)
);
create index if not exists ix_outbox_messages_occurred_at_unpublished on aud.outbox_messages (occurred_at) where (published_at is null); -- dispatcher reads unpublished messages in order

-- aud.security_events: SecurityEvents [KRN-AUD-02]
create table if not exists aud.security_events (
    id uuid not null,
    occurred_at timestamptz not null,
    event_type text not null,
    actor text,
    subject text,
    severity text not null,
    details jsonb not null,
    created_at timestamptz not null,
    created_by uuid not null,
    constraint pk_security_events primary key (id),
    constraint ck_security_events_event_type_code check (length(event_type) between 1 and 40 and event_type = btrim(event_type)),
    constraint ck_security_events_severity check (severity in ('info', 'warning', 'critical'))
);
create index if not exists ix_security_events_occurred_at on aud.security_events (occurred_at); -- listed in the data design
create or replace trigger tg_security_events_append_only before update or delete on aud.security_events for each row execute function aud.tg_refuse_change();
create or replace trigger tg_security_events_no_truncate before truncate on aud.security_events for each statement execute function aud.tg_refuse_change();

-- aud.subject_keys: Per-person encryption keys for personal data in the audit log; destroying a key erases the data [HRM-PRV-04]
create table if not exists aud.subject_keys (
    person_id uuid not null,
    wrapped_key bytea not null,
    destroyed_at timestamptz,
    constraint pk_subject_keys primary key (person_id)
);

